[database]
url = {{db_url}}
pool_size = {{db_pool_size}}

[http]
timeout_ms = {{timeout_ms}}
worker_threads = {{worker_threads}}

[app]
log_level = {{log_level}}
feature_fastpay = {{feature_fastpay}}
# rollout.conf — defaults for the app config rollout tool.
# Every value can be overridden from the environment (ROLLOUT_*); the deploy
# pipeline and the tests use that to point the tool at other directories.

HOSTS_FILE=${ROLLOUT_HOSTS_FILE:-$ROLLOUT_HOME/conf/hosts.conf}
TEMPLATE=${ROLLOUT_TEMPLATE:-$ROLLOUT_HOME/conf/app.conf.tpl}
RELEASE_DIR=${ROLLOUT_RELEASE_DIR:-$ROLLOUT_HOME/releases}
WORK_DIR=${ROLLOUT_WORK_DIR:-/var/tmp/rollout}
# Rendered files land in $OUT_DIR/hosts/<host>/app.conf; the host agents
# pick them up from there.
OUT_DIR=${ROLLOUT_OUT_DIR:-/srv/rollout}

# Configuration service CLI (vendor). Its state directory comes from CFGSVC_HOME.
CFGSVC=${ROLLOUT_CFGSVC:-$ROLLOUT_HOME/vendor/bin/cfgsvc}

# Key scopes, most specific first: host.<host>.<s>, pool.<pool>.<s>, global.<s>
SCOPES="host pool global"
# render.sh — app.conf for one host from the template.

# render_host HOST POOL RELEASE — writes the file to stdout.
render_host() {
  local host=$1 pool=$2 release=$3 s val script=""
  for s in $(template_settings); do
    val=$(resolve "$host" "$pool" "$s") || { warn "no value for $s on $host"; return 1; }
    case "$val" in *$'\n'*) warn "multi-line value for $s on $host"; return 1 ;; esac
    script="${script}s|{{$s}}|$(sed_repl_escape "$val")|g;"
  done
  printf '# generated by rollout for %s (pool %s, release %s) — do not edit on the host\n' \
    "$host" "$pool" "$release"
  sed -e "$script" "$TEMPLATE"
}

# rendered_value FILE SETTING-LINE-KEY — value of "key = value" in a rendered file
rendered_value() {
  awk -v k="$2" '{ i = index($0, " = ") } i && substr($0, 1, i - 1) == k { print substr($0, i + 3); exit }' "$1"
}
1:# Test helpers. Each test file sources this, calls t_setup, then asserts.
2:T_HOME=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
3:T_FAIL=0
4:T_PASS=0
5:
6:t_setup() {
7:  T_WORK=$(mktemp -d)
8:  trap 't_cleanup' EXIT
9:  export ROLLOUT_WORK_DIR="$T_WORK/work"
10:  export ROLLOUT_OUT_DIR="$T_WORK/out"
11:  export ROLLOUT_HOSTS_FILE="$T_HOME/conf/hosts.conf"
12:  export ROLLOUT_RELEASE_DIR="$T_HOME/releases"
13:  export CFGSVC_HOME="$T_WORK/cfgsvc"
14:  mkdir -p "$CFGSVC_HOME"
15:}
16:
17:t_cleanup() { [ -n "${T_WORK:-}" ] && rm -rf "$T_WORK"; }
18:
19:# Loads the libraries into the test shell (for unit tests).
20:t_source_libs() {
21:  export LC_ALL=C.UTF-8
22:  export ROLLOUT_HOME="$T_HOME"
23:  . "$T_HOME/steps/_env.sh"
24:}
25:
26:rollout() { "$T_HOME/bin/rollout" "$@"; }
27:
28:ok()   { T_PASS=$((T_PASS + 1)); printf 'ok   - %s\n' "$1"; }
29:fail() { T_FAIL=$((T_FAIL + 1)); printf 'FAIL - %s\n' "$1"; [ -n "${2:-}" ] && printf '       %s\n' "$2"; return 0; }
30:
31:assert_eq() {
32:  if [ "$2" = "$3" ]; then ok "$1"; else fail "$1" "expected [$3] got [$2]"; fi
33:}
34:
35:assert_contains() {
36:  if printf '%s' "$2" | grep -qF -- "$3"; then ok "$1"; else fail "$1" "missing [$3]"; fi
37:}
38:
39:assert_rc() {
40:  if [ "$2" -eq "$3" ]; then ok "$1"; else fail "$1" "expected exit $3 got $2"; fi
41:}
42:
43:t_done() {
44:  printf '# %s: %d passed, %d failed\n' "$(basename "$0")" "$T_PASS" "$T_FAIL"
45:  [ "$T_FAIL" -eq 0 ]
46:}

